-- Migration 017 — Consultation popup: real content & image
-- Run this via admin/run-migrations.php (recommended) or paste into
-- phpMyAdmin if you prefer to apply it manually.
--
-- Widens site_popup.image from VARCHAR(255) to TEXT so it can hold a
-- built-in data: URI graphic (no /uploads/ file needed), and replaces
-- the popup's title, description, points, and image with real Drawlead
-- content instead of placeholder text.
--
-- IMPORTANT: only run the UPDATE below if you have NOT already
-- customized the popup in Admin -> Popup -- it will overwrite whatever is
-- currently saved. admin/run-migrations.php guards this automatically
-- (the UPDATE only fires once, the first time this migration runs); if
-- you are applying this file by hand instead, run the ALTER TABLE first
-- and skip the UPDATE if you already have real content saved.

ALTER TABLE site_popup MODIFY COLUMN image TEXT;

UPDATE site_popup SET
  image = 'data:image/svg+xml;base64,',
  image_alt = 'Free 30-minute consultation with a Drawlead specialist',
  title = 'Build Your Business OS',
  description = 'Book a free 30-minute call with a Drawlead specialist. We map your current workflows and show you exactly what a unified ERP, ecommerce, and marketing system looks like for your business, with no obligation.',
  points = 'Custom ERP built around your workflows
Ecommerce and marketing systems that connect
AI automation for repetitive work
Free, no-obligation consultation'
WHERE id = 1;
